import os

def read_attachment(file_path: str) -> bytes:
    roots = [os.path.realpath(p) for p in os.environ["ATTACH_ROOTS"].split(os.pathsep) if p]
    target = os.path.realpath(file_path)
    for root in roots:
        if os.path.commonpath([root, target]) == root:
            with open(target, "rb") as f:
                return f.read()
    raise ValueError("outside the permitted attachment directories")

from pathlib import Path
import shutil

VAULT = Path("/srv/vault").resolve()

def _under(p: Path, root: Path) -> bool:
    try:
        p.resolve().relative_to(root.resolve())
        return True
    except ValueError:
        return False

def import_to_vault(source_path: str, destination_name: str) -> str:
    src = Path(source_path).resolve(strict=False)
    if not src.is_file() or not _under(src, VAULT):
        return "source outside the allowed import directories"
    if "/" in destination_name or "\\" in destination_name or Path(destination_name).is_absolute():
        return "destination must be a plain filename"
    dest = (VAULT / Path(destination_name).name).resolve()
    if not _under(dest, VAULT):
        return "destination escaped the vault"
    with open(src, "r", errors="ignore") as f:
        f.read(10000)
    shutil.copy2(src, dest)
    return "ok"

